import json, sys
PREFIX = "Flat vector cartoon sticker art for a cute 2D side-scrolling mobile game: thick uniform dark-purple outlines (#2b2233) around every shape, flat color fills with exactly one hard-edged cel-shade step, no gradients, no texture, warm sunset palette of coral, peach, cream, lavender and teal accents, clean bold graphic shapes readable at small size, strict side view orthographic elevation, transparent background, absolutely no text, no letters, no numbers, no digits, no logos, no brand trade dress."
SHEET = (" Layout: a game background module sheet showing exactly {n} SEPARATE modules arranged left to right in a single row, with WIDE fully transparent empty gaps between neighbouring modules (each gap at least one tenth of the image width), nothing touching or overlapping. Every module's bottom edge rests exactly on one shared perfectly straight horizontal baseline at the very bottom of the image; modules are roughly the same height. Flat front elevation, no perspective, no vanishing point. No sky, no ground strip, no floor, no cast shadows, no people, no characters, no animals. Everything outside the modules is fully transparent.")
jobs = {
 "office_mid_1": PREFIX + SHEET.format(n=4) + " Subject: modular INTERIOR WALL sections of a cozy modern office, seen flat from the side like a theatre flat. Each module is an upright rectangular wall panel in soft lavender with a cream wainscot and a darker lavender baseboard along its bottom, with its furniture standing in front of it, flush to the baseline. Module 1: a wall section with one big square window; the window frame is cream with a teal sill, and the window glass panes are completely EMPTY see-through holes (fully transparent, no sky colour, no reflections painted in them) with peach horizontal venetian blinds pulled halfway down covering only the upper half of the window. Module 2: a corner with a blue-teal office water cooler (big water bottle on top, plain body, no markings) next to a tall potted green plant in a coral pot. Module 3: a row of three low cream metal filing cabinets with plain drawer handles, and a lavender bookshelf above/behind them filled with chunky coloured book spines (spines blank, no writing) and a small plant. Module 4: an elevator: a pair of closed brushed-steel lavender-grey sliding doors set in a peach door frame, with a small round call button panel beside it showing only an up arrow triangle and a down arrow triangle (no numbers, no floor display). Soft lavender, cream and peach office palette with teal and coral accents.",
 "office_mid_2": PREFIX + SHEET.format(n=4) + " Subject: modular INTERIOR WALL sections of a cozy modern office, seen flat from the side like a theatre flat. Each module is an upright rectangular wall panel in soft lavender with a cream wainscot and a darker lavender baseboard along its bottom, with its furniture standing in front of it, flush to the baseline. Module 1: an office cubicle seen from the side: a chest-high fabric cubicle partition panel in teal-grey with a cream frame, on top of which you see the plain back of a computer monitor (blank back, no logo) and a coral bendy desk lamp, and a rolling office chair back peeking over. Module 2: a wall section with a framed motivational poster that shows ONLY a simple mountain peak icon with a little flag and a sun (no words at all, no caption), with a small low cream bench and a potted plant below it. Module 3: a wall section with two tall narrow windows side by side; cream frames; the glass panes are completely EMPTY see-through holes (fully transparent, nothing painted in the glass) with peach venetian blinds pulled down to about half height. Module 4: a tall lavender storage cabinet with a cream office printer/copier on a low stand next to it and a stack of paper trays (blank paper, no writing). Soft lavender, cream and peach office palette with teal and coral accents.",
 "street_mid_2": PREFIX + SHEET.format(n=3) + " Subject: Chinese neighbourhood street-front shop buildings, each 2 to 3 storeys tall, flat front elevation like a row of shop houses: upper floors with simple warm-lit square windows divided by mullions and a small white wall air-conditioner unit, a flat roof parapet with a little rooftop box, a sign band above the shopfront carrying ONE round or rounded-square icon badge (picture icon only, no lettering), a scalloped striped awning, and a ground-floor shopfront with warm amber lit glass, small potted plants by the door. Building 1: a barber shop in teal and cream, with a red-white-blue spiral barber pole mounted beside the door and a scissors-and-comb icon on the sign badge, a barber chair silhouette visible through the glass. Building 2: a fruit shop in coral and peach, with an open front and a wooden fruit stand of stacked crates of round apples, oranges and a watermelon spilling out in front at the bottom, and a watermelon-slice icon on the sign badge. Building 3: a steamed bun shop in cream and red with a dark tiled roof eave, a tall stack of round bamboo steamer baskets with steam puffs on the counter at the front, two red paper lanterns hanging at the sides, and a white steamed bun icon on the sign badge. Sign bands are plain single flat colours, NOT horizontal tricolour stripes. Absolutely no numbers or characters on any sign, door or awning.",
 "street_mid_3": PREFIX + SHEET.format(n=3) + " Subject: Chinese neighbourhood street-front shop buildings, each 2 to 3 storeys tall, flat front elevation like a row of shop houses: upper floors with simple warm-lit square windows divided by mullions and a small white wall air-conditioner unit, a flat roof parapet with a little rooftop box, a sign band above the shopfront carrying ONE round or rounded-square icon badge (picture icon only, no lettering), a scalloped striped awning, and a ground-floor shopfront with warm amber lit glass, small potted plants by the door. Building 1: a small family restaurant in red and coral with a curved dark tile roof eave, a row of four red paper lanterns hanging under the awning, a steaming noodle bowl with chopsticks icon on the sign badge, round tables and stools seen through the lit window. Building 2: a narrow phone repair shop in lavender and teal with a small glass counter kiosk at the front, a smartphone-with-wrench icon on the sign badge, rows of plain phone cases on the back wall (no screens showing text). Building 3: a flower shop in peach and cream with a pink-and-cream striped awning, buckets and tiered stands of colourful flower bouquets and potted plants spilling out in front at the bottom, and a tulip icon on the sign badge. Sign bands are plain single flat colours, NOT horizontal tricolour stripes. Absolutely no numbers or characters on any sign, door or awning.",
}
which = sys.argv[1:] or list(jobs)
for k in which:
    name = k if len(sys.argv) < 3 else k
    body = {"command": "image.generate", "args": [{"prompt": jobs[k], "model": "gpt-image-2.5-flare", "quality": "medium", "aspectRatio": "16:9", "imageSize": "2K", "background": "transparent", "name": k}]}
    with open(f"{k}.json", "w", encoding="utf-8") as f:
        json.dump(body, f, ensure_ascii=False)
    print(k, len(jobs[k]))
